$cards=[['Invoiced revenue','revenue','trending-up','', 'Net issued invoice value in the selected period'],['Cash received','cash','wallet','green','Recorded, non-reversed receipts in the selected period'],['Outstanding balance','outstanding','file-invoice','amber','Selected-period issued invoices less all applied receipts'],['Recorded expenses','expenses','receipt','purple','Active recorded business expenses in the selected period']];foreach($cards as [$label,$key,$ic,$color,$definition]):$change=(float)$prev[$key]!==0?round(((float)$summary[$key]-(float)$prev[$key])/abs((float)$prev[$key])*100,1):null; ?><a class="kpi" href="<?= $key==='cash'?'payments.php':($key==='expenses'?'expenses.php':'invoices.php') ?>" title="<?= e($definition) ?>"><div class="kpi-top"><span><?= $label ?></span><span class="kpi-icon <?= $color ?>"><?= icon($ic) ?></span></div><div class="kpi-value"><?= money($summary[$key]) ?></div><div class="kpi-bottom"><?php if($change!==null): ?><span class="change <?= $change<0?'negative':'' ?>"><?= icon($change<0?'arrow-down-right':'arrow-up-right') ?><?= abs($change) ?>%</span><span>vs. previous period</span><?php else: ?><span>No previous-period activity</span><?php endif; ?></div></a><?php endforeach; ?></div>
<?php
$trend=['labels'=>[],'revenue'=>[],'expenses'=>[]];$group=$days>90?'%Y-%m':'%Y-%m-%d';$revs=rows("SELECT DATE_FORMAT(issue_date,?) period,SUM(total) amount FROM documents WHERE business_id=? AND type='invoice' AND status='Issued' AND issue_date BETWEEN ? AND ? GROUP BY period",[$group,bid(),$start,$end]);$exps=rows("SELECT DATE_FORMAT(expense_date,?) period,SUM(amount) amount FROM expenses WHERE business_id=? AND status='Active' AND expense_date BETWEEN ? AND ? GROUP BY period",[$group,bid(),$start,$end]);$rmap=array_column($revs,'amount','period');$emap=array_column($exps,'amount','period');$cursor=new DateTimeImmutable($start);$endDate=new DateTimeImmutable($end);if($days>90)$cursor=$cursor->modify('first day of this month');$i=0;while($cursor<=$endDate&&$i++<370){$k=$cursor->format($days>90?'Y-m':'Y-m-d');$trend['labels'][]=$cursor->format($days>90?'M Y':'d M');$trend['revenue'][]=(float)($rmap[$k]??0);$trend['expenses'][]=(float)($emap[$k]??0);$cursor=$cursor->modify($days>90?'+1 month':'+1 day');}
[$statusSql,$statusParams]=document_list_sql('invoice','',[$start,$end]);$statuses=['Paid'=>0,'Partially Paid'=>0,'Issued'=>0,'Overdue'=>0,'Draft'=>0];foreach(rows("SELECT derived_status,COUNT(*) count FROM ($statusSql) stats GROUP BY derived_status",$statusParams) as $stat)if(isset($statuses[$stat['derived_status']]))$statuses[$stat['derived_status']]=(int)$stat['count'];
?><div class="dashboard-charts"><section class="panel"><div class="panel-head"><div><h2>Revenue & expenses</h2><p>A little perspective on your business performance.</p></div><a class="btn link" href="reports.php?report=revenue">View report <?= icon('arrow-up-right') ?></a></div><div class="chart-legend"><span><i class="legend-dot"></i>Invoiced revenue</span><span><i class="legend-dot gray"></i>Expenses</span></div><div class="chart-wrap"><canvas id="revenue-chart" role="img" aria-label="Revenue <?= e(money($summary['revenue'])) ?> and expenses <?= e(money($summary['expenses'])) ?> from <?= e($start) ?> to <?= e($end) ?>"></canvas></div></section><section class="panel"><div class="panel-head"><div><h2>Invoice overview</h2><p>Keep an eye on your collections.</p></div><?= icon('dots') ?></div><div class="donut-wrap"><canvas id="invoice-chart" role="img" aria-label="Invoice status distribution: <?= e(implode(', ',array_map(fn($k,$v)=>$k.' '.$v,array_keys($statuses),$statuses))) ?>"></canvas><div class="donut-center"><strong><?= array_sum($statuses) ?></strong><span>Total invoices</span></div></div><div class="status-legend"><?php $colors=['','green','amber','red','gray'];$i=0;foreach($statuses as $label=>$count): ?><div><span><i class="legend-dot <?= $colors[$i++] ?>"></i><?= e($label) ?></span><strong><?= $count ?></strong></div><?php endforeach; ?></div></section></div><script type="application/json" id="dashboard-data"><?= json_encode(['trend'=>$trend,'status'=>['labels'=>array_keys($statuses),'counts'=>array_values($statuses)]],JSON_HEX_TAG|JSON_HEX_AMP) ?></script>
