<div class="middle-grid"><?php if(can('invoices.view')): ?><section class="panel"><div class="table-title"><h2>Recent invoices</h2><a href="invoices.php">View all invoices <?= icon('arrow-right') ?></a></div><div class="table-scroll"><table><thead><tr><th>INVOICE</th><th>CUSTOMER</th><th>AMOUNT</th><th>STATUS</th><th>DUE DATE</th><th></th></tr></thead><tbody><?php $recent=list_documents('invoice','',5,0,[$start,$end]);foreach($recent as $i=>$d): ?><tr><td><a href="invoice-view.php?id=<?= $d['id'] ?>"><strong><?= e($d['number']) ?></strong></a><span class="sub"><?= date_label($d['issue_date']) ?></span></td><td><div class="cell-person"><span class="avatar <?= ['blue','green','amber',''][($i)%4] ?>"><?= e(initials($d['customer_name'])) ?></span><span><?= e($d['customer_name']) ?></span></div></td><td><strong><?= money($d['total']) ?></strong></td><td><?= badge(document_status($d)) ?></td><td><?= date('d M',strtotime($d['due_date'])) ?></td><td><a href="invoice-view.php?id=<?= $d['id'] ?>" class="icon-btn" aria-label="View <?= e($d['number']) ?>"><?= icon('chevron-right') ?></a></td></tr><?php endforeach;if(!$recent): ?><tr><td colspan="6" class="empty">No invoices for this period.</td></tr><?php endif; ?></tbody></table></div><div class="table-foot"><span>Showing your latest <?= count($recent) ?> invoices</span><span><?= e(date_label($start)) ?> – <?= e(date_label($end)) ?></span></div></section><?php endif; ?>
<?php if(can('tasks.view')): ?><section class="panel"><div class="table-title"><h2>Upcoming tasks <span class="badge neutral"><?= (int)scalar("SELECT COUNT(*) FROM tasks WHERE business_id=? AND status IN ('Pending','In Progress')",[bid()]) ?></span></h2><a href="tasks.php">View all <?= icon('arrow-right') ?></a></div><div class="tasks-list"><?php $tasks=rows("SELECT * FROM tasks WHERE business_id=? AND status IN ('Pending','In Progress') ORDER BY due_date,id LIMIT 4",[bid()]);foreach($tasks as $t): ?><div class="task-row"><?php if(can('tasks.complete')): ?><form method="post" action="tasks.php"><?php csrf_field(); ?><input type="hidden" name="action" value="complete"><input type="hidden" name="id" value="<?= $t['id'] ?>"><input type="checkbox" aria-label="Complete <?= e($t['title']) ?>" data-task-check></form><?php else: ?><?= icon('circle') ?><?php endif; ?><div><strong><?= e($t['title']) ?></strong><small><?= icon('calendar') ?><?= $t['due_date']===date('Y-m-d')?'Today':date_label($t['due_date']) ?><?php if($t['due_date']<date('Y-m-d')): ?><span class="text-red">· Overdue</span><?php endif; ?></small></div><span class="priority <?= e($t['priority']) ?>"><?= e($t['priority']) ?></span></div><?php endforeach; if(!$tasks): ?><div class="empty">You’re all caught up.</div><?php endif; ?></div><a class="panel-foot" href="tasks.php?edit=new"><?= icon('plus') ?> Add a new task</a></section><?php endif; ?></div>
<div class="bottom-grid"><?php if(can('leads.view')): $stages=rows("SELECT stage,COUNT(*) count,SUM(value) value FROM leads WHERE business_id=? AND status='Active' GROUP BY stage",[bid()]);$stageMap=array_column($stages,'count','stage');$totalLeads=array_sum($stageMap); ?><section class="panel"><div class="panel-head"><div><h2>Sales pipeline</h2><p>Every opportunity, one step closer.</p></div><a href="leads.php" aria-label="View sales pipeline" class="icon-btn"><?= icon('arrow-up-right') ?></a></div><div class="pipeline-list"><?php foreach(['New','Qualified','Proposal','Negotiation','Won'] as $st): $n=$stageMap[$st]??0; ?><a href="leads.php?stage=<?= e($st) ?>" class="pipeline-row"><span><?= e($st) ?></span><progress class="pipeline-track" max="<?= max(1,$totalLeads) ?>" value="<?= $n ?>"><?= $n ?></progress><strong><?= $n ?></strong></a><?php endforeach; ?></div><div class="pipeline-summary"><span>Total pipeline value</span><strong><?= money(array_sum(array_column(array_filter($stages,fn($s)=>!in_array($s['stage'],['Won','Lost'])),'value'))) ?></strong></div></section><?php endif; ?>
<?php if(can('customers.view')&&can('invoices.view')): ?><section class="panel"><div class="panel-head"><div><h2>Top customers</h2><p>Your strongest business relationships.</p></div><a class="icon-btn" href="customers.php" aria-label="View customers"><?= icon('arrow-up-right') ?></a></div><div class="customer-rank"><?php $top=rows("SELECT c.id,c.name,c.company,SUM(d.total) billed,COUNT(d.id) count FROM customers c JOIN documents d ON d.customer_id=c.id AND d.business_id=c.business_id AND d.type='invoice' AND d.status='Issued' AND d.issue_date BETWEEN ? AND ? WHERE c.business_id=? GROUP BY c.id ORDER BY billed DESC LIMIT 4",[$start,$end,bid()]);foreach($top as $i=>$c): ?><a class="rank-row" href="customer-view.php?id=<?= $c['id'] ?>"><span class="avatar <?= ['blue','green','amber',''][$i] ?>"><?= e(initials($c['name'])) ?></span><div><strong><?= e($c['name']) ?></strong><small><?= $c['count'] ?> invoices</small></div><b><?= money($c['billed']) ?></b></a><?php endforeach;if(!$top): ?><p class="empty">Your top customers will appear here.</p><?php endif; ?></div></section><?php endif; ?>
