<?php if(can('reports.view')):require dirname(__DIR__).'/app/analytics.php';$extraCharts=analytics_charts($start,$end); ?><details class="analytics-details panel"><summary>Explore deeper insights <span><?= count($extraCharts) ?> additional views · <?= date_label($start) ?> – <?= date_label($end) ?></span><?= icon('chevron-down') ?></summary><div class="analytics-grid"><?php foreach($extraCharts as $i=>$chart): ?><section class="panel"><div class="panel-head"><div><h2><?= e($chart['title']) ?></h2><p>Authoritative records · <?= date_label($start) ?> – <?= date_label($end) ?></p></div><a class="icon-btn" href="<?= e($chart['link']) ?>" aria-label="Open <?= e($chart['title']) ?> report"><?= icon('arrow-up-right') ?></a></div><div class="chart-wrap"><canvas id="insight-<?= $i ?>" role="img" aria-label="<?= e($chart['title'].': '.implode(', ',array_map(fn($label,$value)=>$label.' '.$value,$chart['labels'],$chart['datasets'][0]['data']))) ?>"></canvas></div></section><?php endforeach; ?></div></details><script type="application/json" id="insight-data"><?= json_encode($extraCharts,JSON_HEX_TAG|JSON_HEX_AMP) ?></script><?php endif;page_end(); ?>
